const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  ImageRun, Table, TableRow, TableCell, WidthType, ShadingType,
  BorderStyle, TableOfContents, PageBreak, LevelFormat, convertInchesToTwip,
} = require("docx");

const FIG = path.join(__dirname, "..", "figures");

function H(text, level) {
  return new Paragraph({ text, heading: level, spacing: { before: 280, after: 140 } });
}
function P(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, italics: opts.italics, bold: opts.bold, size: opts.size })],
    spacing: { after: 160 },
    alignment: opts.align || AlignmentType.JUSTIFIED,
  });
}
function PR(parts, opts = {}) {
  return new Paragraph({
    children: parts.map(p => new TextRun({ text: p.text, bold: p.bold, italics: p.italics })),
    spacing: { after: 160 },
    alignment: opts.align || AlignmentType.JUSTIFIED,
  });
}
function Bullet(text, level = 0) {
  return new Paragraph({
    children: [new TextRun(text)],
    bullet: { level },
    spacing: { after: 90 },
  });
}
function Caption(text) {
  return new Paragraph({
    children: [new TextRun({ text, italics: true, size: 20 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 240, before: 60 },
  });
}
function FigLabel(n) {
  return new Paragraph({
    children: [new TextRun({ text: `Figure ${n}`, size: 20 })],
    alignment: AlignmentType.CENTER,
    spacing: { after: 0, before: 60 },
  });
}
function Img(file, widthPx, heightPx, caption, figNum) {
  const buf = fs.readFileSync(`${FIG}/${file}`);
  return [
    new Paragraph({
      children: [new ImageRun({ data: buf, transformation: { width: widthPx, height: heightPx }, type: "png" })],
      alignment: AlignmentType.CENTER,
      spacing: { before: 160 },
    }),
    FigLabel(figNum),
    Caption(caption),
  ];
}
function cell(text, opts = {}) {
  return new TableCell({
    width: { size: opts.width || 2000, type: WidthType.DXA },
    shading: (opts.header && opts.special) ? { type: ShadingType.CLEAR, color: "auto", fill: "D9E2F3" } : undefined,
    borders: (opts.header && !opts.special) ? { bottom: { style: BorderStyle.SINGLE, size: 4, color: "000000" } } : undefined,
    children: [new Paragraph({
      children: [new TextRun({ text: String(text), bold: !!(opts.header && opts.special), size: 20 })],
      alignment: opts.align || AlignmentType.LEFT,
    })],
  });
}
function table(headers, rows, widths, opts = {}) {
  const w = widths || headers.map(() => Math.floor(9000 / headers.length));
  const special = !!opts.specialHeader;
  return new Table({
    width: { size: 9000, type: WidthType.DXA },
    columnWidths: w,
    rows: [
      new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, { header: true, special, width: w[i] })) }),
      ...rows.map(r => new TableRow({ children: r.map((v, i) => cell(v, { width: w[i] })) })),
    ],
  });
}

